{"content":"import puppeteer from 'puppeteer-core';

(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/usr/bin/chromium-browser',
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox'],
  });
  const page = await browser.newPage();
  await page.goto('http://127.0.0.1:5173/', { waitUntil: 'networkidle2' });
  await page.setViewport({ width: 1280, height: 800 });
  await page.waitForTimeout(1000);

  const header = await page.$('[data-component="Header"]');
  const footer = await page.$('[data-component="Footer"]');
  const buttons = await page.$$('[data-component="Button"]');
  const greeting = await page.evaluate(() => {
    const h1 = document.querySelector('h1');
    return { text: h1?.innerText, color: h1 ? getComputedStyle(h1).color : null, fontSize: h1 ? getComputedStyle(h1).fontSize : null };
  });

  console.log('Header present:', !!header);
  console.log('Footer present:', !!footer);
  console.log('Button count:', buttons.length);
  console.log('Greeting:', greeting);

  // Click each button and check greeting color
  for (const btn of buttons) {
    const label = await page.evaluate(el => el.innerText, btn);
    await btn.click();
    await page.waitForTimeout(200);
    const color = await page.evaluate(() => {
      const h1 = document.querySelector('h1');
      return h1 ? getComputedStyle(h1).color : null;
    });
    console.log(`After clicking ${label}:`, color);
  }

  await page.screenshot({ path: '/tmp/hello-app-verify.png', fullPage: false });
  await browser.close();
})();
